 @Test void procurementOriginalGetsTypedInputWithoutFakeClaimAndNeverRepeatsExpense(){
  var origin=purchase();UUID basis=confirmedBasis(origin);as(owner,"finance.tax");var command=decision(basis,"6","0");call(()->tax.decision(command));call(()->tax.decision(command));
  assertThat(jdbc.queryForMap("select source_kind,invoice_id,basis_id,claimed_tax from fb_input_tax where id=?",command.requestId())).containsEntry("source_kind","PROCUREMENT").containsEntry("invoice_id",origin.get("invoice")).containsEntry("basis_id",basis).containsEntry("claimed_tax",new BigDecimal("6.00"));assertThat(jdbc.queryForObject("select count(*) from finance_claim where hotel_id=?",Integer.class,hotel)).isZero();assertThat(jdbc.queryForObject("select count(*) from fb_input_tax where basis_id=?",Integer.class,basis)).isEqualTo(1);assertThat(jdbc.queryForObject("select sum(actual) from fbu_flow where document_id=?",BigDecimal.class,origin.get("recognition"))).isEqualByComparingTo("106");assertThat(jdbc.queryForObject("select count(*) from fa_source_event where source_id=? and source_type='FB_INPUT_TAX'",Integer.class,command.requestId())).isEqualTo(1);
  assertThatThrownBy(()->call(()->tax.decision(decision(basis,"0.01","0")))).hasMessageContaining("累计抵扣");assertThatThrownBy(()->call(()->tax.decision(decision(basis,"7","7")))).hasMessageContaining("本次抵扣");assertThatThrownBy(()->call(()->tax.decision(decision(basis,"0","6.01")))).hasMessageContaining("累计转出");
 }
