  as(finance,"finance.read","finance.tax");var reconciled=call(()->bankControl.statement(bank,DAY));assertThat(reconciled).containsEntry("complete",false).containsEntry("statementBalance","994.00").containsEntry("controlledCashBalance","996.00").containsEntry("difference","-2.00");assertThat(FinanceV2Support.rows(reconciled.get("cashJournal"))).anySatisfy(row->assertThat(row).containsEntry("sourceKind","FB_MATCH_REVERSAL").containsEntry("amount","-2.00"));assertThat(jdbc.queryForObject("select amount from fo_bank_transaction where id=?",BigDecimal.class,transaction)).isEqualByComparingTo("6");
